-- ===================== Fichas novas: AS06 (Panacea) e NPCs do AS07 =====================

insert into creatures (source_id, name, vd, flavor_text, descritores, tamanho, categoria, tipo_criatura, presenca_dt, presenca_dano, presenca_nex_imune, percepcao, iniciativa, defesa, fortitude, reflexos, vontade, pv_maximo, pv_machucado, resistencias, vulnerabilidades, atributos, pericias, deslocamento, habilidades, acoes, image_url, sort_order)
values
((select id from sources where slug = 'arquivos_secretos_06'), 'Alice Cruzes', 40, 'Diretora de algumas instalações da Panacea. Mestra estrategista, capaz de analisar cenários complexos em segundos e coordenar seus aliados com precisão cirúrgica.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '2d20+5', '2d20', 18, '1d20', '2d20+5', '2d20+10', 30, 15, null, null, '{"agi":2,"for":1,"int":4,"pre":2,"vig":1}', 'Diplomacia 2d20+10, Enganação 2d20+10, Intimidação 2d20+5, Intuição 2d20+5, Medicina 4d20+5, Tática 4d20+10', '9m | 6', '[{"nome":"Diretora","descricao":"Alice nunca se expõe desnecessariamente ao perigo. Ela está sempre acompanhada por dois seguranças da Panacea."}]', '[{"tipo":"Padrão","nome":"Pistola, à distância (curto)","teste":"2d20+5, crítico 18","dano":"1d12+5 balístico"},{"tipo":"Reação","nome":"Reencontro","dano":"8d6 perfuração (Reflexos DT 15 reduz à metade)","descricao":"Ao chegar a 0 PV, ativa um dispositivo explosivo que carrega consigo; atinge todos os seres em um raio de 6m."},{"tipo":"Movimento","nome":"Coordenar Equipe","descricao":"Emite instruções rápidas e precisas a um aliado em alcance curto. Se, em seu turno, o aliado acatar as ordens e elas resultarem em um teste, ele recebe +5 nesse teste."},{"tipo":"Padrão","nome":"Recursos Humanos","dano":"6d6 perfuração (Reflexos DT 15 reduz à metade)","descricao":"Os seguranças carregam explosivos implantados no corpo. Alice escolhe um segurança aliado em alcance longo: o dispositivo explode, matando o segurança e atingindo todos os seres em um raio de 6m."}]', '/conteudo/as06/criaturas/alice-cruzes.webp', 120),
((select id from sources where slug = 'arquivos_secretos_06'), 'Ketan Arjuna', 100, 'Chefe de segurança da Panacea e representante da sede Durgā. Funcionalmente frio, pragmaticamente violento e resistente ao estresse; usa uma prótese robótica como arma e escudo.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '2d20+5', '4d20+10', 20, '1d20+5', '4d20+10', '2d20+5', 90, 45, null, null, '{"agi":4,"for":3,"int":2,"pre":2,"vig":1}', 'Atletismo 3d20+10, Intimidação 2d20+10, Tática 2d20+10, Tecnologia 2d20+10', '9m | 6', '[{"nome":"Armado e Preparado","descricao":"Ketan tem uma ação padrão adicional por rodada. Além disso, quando faz um ataque usando uma arma, causa +1 dado de dano extra do mesmo tipo."},{"nome":"Prótese Robótica","descricao":"Avançada prótese tecnológica da Panacea, integrada ao seu estilo de combate. Pode ser alvo de ataques separadamente (Defesa 25, RD 5 e 45 PV). Se for destruída, Ketan perde a ação padrão adicional e as ações Punho de Aço, Reparo na Hora, Atirar e Fatiar e Defesa Improvisada."}]', '[{"tipo":"Padrão","nome":"Revólver, à distância (curto)","teste":"4d20+10, crítico x3","dano":"3d6+10 balístico"},{"tipo":"Padrão","nome":"Machadinha, corpo a corpo","teste":"3d20+10, crítico x3","dano":"2d6+10 corte"},{"tipo":"Padrão","nome":"Punhalada, corpo a corpo","teste":"3d20+10, crítico x3","dano":"2d4+10 perfuração"},{"tipo":"Padrão","nome":"Punho de Aço, corpo a corpo","teste":"3d20+10, crítico 18","dano":"2d10+10 impacto mais 2d4 eletricidade"},{"tipo":"Reação","nome":"Atirar e Fatiar","descricao":"Quando acerta um ataque corpo a corpo contra um alvo já atingido por um de seus ataques à distância nesta rodada, o ataque corpo a corpo causa +1 dado de dano extra do mesmo tipo."},{"tipo":"Reação","nome":"Coice","descricao":"Ao atacar com o Punho de Aço, a prótese sofre metade do dano que ele causar."},{"tipo":"Reação","nome":"Defesa Improvisada","descricao":"Uma vez por rodada, quando for atingido por um ataque, interpõe a prótese: ela sofre todo o dano no lugar de Ketan. Se a prótese for destruída por esse ataque, Ketan sofre 2d10 pontos de dano de eletricidade."},{"tipo":"Padrão","nome":"Reparo na Hora","descricao":"Com ferramentas improvisadas, realiza reparos emergenciais na prótese, recuperando 10 PV dela."}]', '/conteudo/as06/criaturas/ketan-arjuna.webp', 121),
((select id from sources where slug = 'arquivos_secretos_06'), 'Laila Verdante', 80, 'Parapsicóloga sênior da Panacea, cofundadora do Instituto de Parapsicologia e criadora do Projeto Roseta. Sabe muito bem como aproveitar a fragilidade da psique humana.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '4d20+10', '2d20+5', 19, '1d20', '2d20+5', '4d20+10', 70, 35, null, null, '{"agi":2,"for":1,"int":3,"pre":4,"vig":1}', 'Enganação 4d20+10, Furtividade 2d20+10, Intuição 4d20+10, Ocultismo 3d20+10, Tecnologia 3d20+10', '9m | 6', '[{"nome":"Arruinar Mentes","descricao":"Seres que estejam sofrendo uma ou mais condições mentais são considerados vulneráveis ao dano de Conhecimento causado pelos rituais de Laila."},{"nome":"Rituais (DT 22)","descricao":"Laila pode conjurar os rituais a seguir sem gastar seu custo de PE, até um limite de 6 PE por conjuração, usando a ação apropriada."}]', '[{"tipo":"Padrão","nome":"Arremesso de Agulha, à distância (curto) x2","teste":"2d20+10","dano":"1d4+5 perfuração"},{"tipo":"Reação","nome":"Sedar","descricao":"Seres atingidos pelo arremesso de agulha ficam esmorecidos até o fim da cena (Fortitude DT 22 muda para frustrado)."},{"tipo":"Padrão","nome":"Ritual: Aurora da Verdade (Conhecimento 2)","descricao":"Até o fim da cena, cria um raio de 3m onde nenhum ser pode obter camuflagem ou ficar invisível. Nenhum ser dentro da área pode mentir (Vontade anula esse efeito)."},{"tipo":"Padrão","nome":"Ritual: Enfeitiçar Discente (Conhecimento 1)","descricao":"Dá uma sugestão aceitável de uma ação que uma pessoa em alcance curto deve realizar (Vontade anula). Em combate, por exemplo, que o alvo ataque a conjuradora por último."},{"tipo":"Padrão","nome":"Ritual: Invadir Mente (Conhecimento 2)","dano":"6d6 Conhecimento + atordoado (Vontade reduz à metade e evita a condição)","descricao":"Um ser em alcance médio. Um mesmo alvo só pode ficar atordoado por este ritual uma vez por cena."},{"tipo":"Padrão","nome":"Ritual: Hesitação Forçada Discente (Conhecimento 1)","descricao":"Um ser em alcance curto testa Vontade no início de cada turno. Se falhar, não consegue fazer ações hostis contra Laila e precisa rolar novamente o maior dado de qualquer teste, aceitando o novo valor. Dissipa ao passar no teste duas vezes seguidas ou no fim da cena."}]', '/conteudo/as06/criaturas/laila-verdante.webp', 122),
((select id from sources where slug = 'arquivos_secretos_06'), 'Dr. Neruda', 20, 'Carlos Augusto Neruda, pesquisador da Panacea que estudou o NADA-1. Diferente da maioria, sabe muito bem o que faz lá. E adora o seu trabalho.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '2d20+5', '2d20+5', 14, '1d20', '2d20+5', '2d20+5', 15, 7, null, null, '{"agi":2,"for":0,"int":3,"pre":2,"vig":1}', 'Ciências 3d20+10, Intuição 2d20+5, Medicina 3d20+10, Tecnologia 3d20+10', '9m | 6', '[{"nome":"Veneno Sádico","descricao":"Os venenos do Dr. Neruda maximizam o sofrimento humano. Em seres machucados, seu veneno causa 1d4 pontos de dano mental. Esse dano ignora RD."}]', '[{"tipo":"Padrão","nome":"Seringa, corpo a corpo","teste":"2d20+5","dano":"1d4+5 perfuração"},{"tipo":"Reação","nome":"Veneno na Seringa","descricao":"Ao acertar com a seringa, a vítima perde 2d4 PV, 1 vez por rodada, por 3 rodadas (Fortitude DT 15 muda para 1 rodada). Ele sempre carrega o antídoto e pode ser convencido a entregá-lo."},{"tipo":"Padrão","nome":"Dose Experimental","descricao":"Arremessa um frasco em alcance curto: seres em um raio de 6m ficam enjoados por 1 rodada e fracos até o fim da cena (Fortitude DT 15 evita). Um mesmo alvo só fica enjoado por esta habilidade uma vez por cena."}]', '/conteudo/as06/criaturas/dr-neruda.webp', 123),
((select id from sources where slug = 'arquivos_secretos_06'), 'Cientista da Panacea', 40, 'Uma pessoa cujas habilidades únicas e inteligência notável foram corrompidas pela prática de experimentos antiéticos.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '1d20+5', '2d20+5', 16, '1d20+5', '2d20+5', '1d20+5', 20, 10, 'Perfuração e químico 10 (Traje de Proteção)', null, '{"agi":2,"for":1,"int":4,"pre":1,"vig":1}', 'Ciências 4d20+10, Investigação 4d20+5, Medicina 4d20+5, Sobrevivência 4d20+5, Tecnologia 4d20+5', '9m | 6', '[{"nome":"Seringas com Venenos","descricao":"Escolha um veneno com DT até 25 (OPRPG, p. 293, ou AS06, p. 77). Se acertar um ataque de injetar, o cientista envenena o alvo com o veneno escolhido."},{"nome":"Submissão","descricao":"Se estiver no mesmo ambiente que um manda-chuva da Panacea, seus testes recebem +5. O efeito termina se o manda-chuva sair de cena."},{"nome":"Traje de Proteção","descricao":"Traje hazmat de alta qualidade: +10 em testes de resistência contra efeitos ambientais e infecções, e resistência a dano de perfuração e químico 10."}]', '[{"tipo":"Padrão","nome":"Pancada, corpo a corpo","teste":"1d20+5","dano":"1d4+5 impacto"},{"tipo":"Padrão","nome":"Injetar, corpo a corpo","teste":"1d20+5","descricao":"Aplica o veneno escolhido."}]', '/conteudo/as06/criaturas/cientista.webp', 124),
((select id from sources where slug = 'arquivos_secretos_06'), 'Manda-Chuva da Panacea', 120, 'Um executivo ou funcionário com cargo de gerência, fiel às Indústrias Panacea e disposto a sacrificar todos os seus subalternos pela empresa.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '3d20+10', '2d20', 23, '3d20+5', '2d20', '3d20+10', 120, 60, null, null, '{"agi":2,"for":1,"int":3,"pre":3,"vig":3}', 'Atualidades 3d20+5, Diplomacia 3d20+10, Enganação 3d20+10, Intimidação 3d20+10, Intuição 3d20+10, Ocultismo 3d20+5', '9m | 6', '[{"nome":"Negociador","descricao":"Quando faz um teste de perícia baseado em Presença, pode rolar novamente e ficar com o melhor resultado."},{"nome":"Objeto de Pesquisa","descricao":"Tem um item amaldiçoado determinado pelo mestre guardado consigo e sabe como usá-lo."}]', '[{"tipo":"Padrão","nome":"Pancada, corpo a corpo","teste":"1d20+10","dano":"1d6+5 impacto"},{"tipo":"Padrão","nome":"Pistola, à distância (curto) x2","teste":"2d20+10, crítico 18","dano":"2d12+10 balístico"},{"tipo":"Reação","nome":"Sou Mais Importante","descricao":"Uma vez por rodada, quando é alvo de um efeito negativo e há um subalterno seu na cena em alcance médio, destina o efeito para o funcionário."},{"tipo":"Padrão","nome":"Chamar Reforços","descricao":"Uma vez por cena, traz 1d4+1 seguranças da Panacea para a cena, agindo logo após o manda-chuva na iniciativa."}]', '/conteudo/as06/criaturas/manda-chuva.webp', 125),
((select id from sources where slug = 'arquivos_secretos_06'), 'Segurança da Panacea', 80, 'Um paramilitar muito bem pago, encarregado da força bruta contra criaturas fora de contenção e possíveis visitas indesejadas.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '2d20', '3d20+10', 21, '2d20+5', '3d20+5', '2d20+5', 80, 40, 'RD 5 (Traje de Campo)', null, '{"agi":3,"for":3,"int":1,"pre":2,"vig":2}', 'Atletismo 3d20+10, Intimidação 2d20+5', '9m | 6', '[{"nome":"Bem Pago","descricao":"Se estiver no mesmo ambiente que um manda-chuva da Panacea, seus testes recebem +5. O efeito termina se o manda-chuva sair de cena."},{"nome":"Munição Não Letal","descricao":"Equipado com munições letais e não letais. A menos que receba ordem de atirar para matar, usa munição não letal (balas de borracha ou dardos tranquilizantes)."},{"nome":"Ossos do Ofício","descricao":"+5 em testes de resistência contra efeitos paranormais (rituais, poderes paranormais e afins)."},{"nome":"Traje de Campo","descricao":"Fornece RD 5 e máscara de gás (+10 em Fortitude contra efeitos que dependam de respiração)."}]', '[{"tipo":"Padrão","nome":"Pancada, corpo a corpo x2","teste":"3d20+10","dano":"2d6+10 impacto"},{"tipo":"Padrão","nome":"Pistola, à distância (curto) x2","teste":"3d20+10, crítico 18","dano":"1d12+10 balístico"},{"tipo":"Padrão","nome":"Submetralhadora, à distância (curto) x2","teste":"3d20+10, crítico 19/x3","dano":"3d6+10 balístico"},{"tipo":"Livre","nome":"Agarrar","descricao":"Se acertar uma pancada, pode tentar agarrar o alvo (teste 3d20+10)."},{"tipo":"Movimento","nome":"Derrubar","descricao":"Agarrando um alvo, pode tentar derrubá-lo (teste 3d20+10); continua agarrando de qualquer forma."},{"tipo":"Movimento","nome":"Imobilizar","descricao":"Agarrando um alvo caído, faz uma manobra (teste 3d20+10) para imobilizá-lo: o alvo fica paralisado até ser solto. Manter o alvo imobilizado deixa o segurança indefeso, mas ele pode soltar o alvo como reação."},{"tipo":"Padrão","nome":"Atordoamento","descricao":"Uma vez por cena, flashbang em alcance curto: seres em um raio de 6m ficam atordoados por 1 rodada (Fortitude DT 20 reduz para ofuscado e surdo por 1 rodada)."},{"tipo":"Padrão","nome":"Fragmentação","dano":"8d6 perfuração (Reflexos DT 20 reduz à metade)","descricao":"Uma vez por cena, granada em alcance curto; raio de 6m."},{"tipo":"Padrão","nome":"Gás Lacrimogêneo","dano":"4d6 químico (Fortitude DT 20 reduz à metade e evita enjoado)","descricao":"Uma vez por cena, granada em alcance curto; raio de 6m. Ficam enjoados e asfixiados; fora da área, continuam asfixiados por 1d4 rodadas e enjoados até o fim da cena."},{"tipo":"Padrão","nome":"Incendiária","dano":"6d6 fogo + em chamas (Reflexos DT 20 reduz à metade e evita em chamas)","descricao":"Uma vez por cena, granada em alcance curto; raio de 6m."},{"tipo":"Padrão","nome":"Rajadas","descricao":"Dois ataques com a submetralhadora; cada um com –1d20 no teste (2d20+10), mas causando 1 dado de dano adicional (4d6+10)."}]', '/conteudo/as06/criaturas/seguranca.webp', 126),
((select id from sources where slug = 'arquivos_secretos_06'), 'Hikikomori', 20, 'Criatura humanoide originada do contato entre o vírus infecticídio e um humano solitário, cujo contato com a tecnologia é maior que o contato humano. Seu corpo se contorce para dentro, escondido atrás de periféricos e enrolado em fios. Solitário, mas extremamente agressivo.', '{"Energia","Sangue"}', 'Médio', 'paranormal', null, 14, '2d6 mental', 25, '1d20', '2d20+5', 16, '1d20', '2d20+5', '1d20', 35, 17, 'Energia 5', 'Conhecimento', '{"agi":2,"for":1,"int":1,"pre":1,"vig":1}', null, '9m | 6', '[{"nome":"Casulo Voltaico","descricao":"Enquanto não estiver machucado, drena a energia dos eletrônicos do corpo: cura acelerada 5. Além disso, sempre que for alvo de um ataque corpo a corpo, projeta uma onda elétrica no atacante (2d4 de dano de Energia). Machucado, perde essa habilidade."}]', '[{"tipo":"Padrão","nome":"Disparo Infectado, à distância (curto)","teste":"2d20+5","dano":"2d12 eletricidade"},{"tipo":"Padrão","nome":"Esbarrão Infectado, corpo a corpo","teste":"2d20+5","dano":"2d12 eletricidade"},{"tipo":"Livre","nome":"Infecção","descricao":"Um ser que sofra dano do disparo ou do esbarrão é infectado pelo vírus do infecticídio (Fortitude DT 14 evita; OPRPG, p. 292). Quem passa fica imune até o fim da cena."},{"tipo":"Livre","nome":"Ricochete","descricao":"Ao acertar um esbarrão, pode fazer uma ação de movimento para se deslocar."}]', '/conteudo/as06/criaturas/hikikomori.webp', 127),
((select id from sources where slug = 'arquivos_secretos_06'), 'Marca-Passo', 80, 'Surge da união do vírus infecticídio com pessoas que já tinham implantes tecnológicos ou biohacking (chips, placas de metal, marca-passos). O vírus deforma a tecnologia do corpo, expelindo-a pela carne.', '{"Energia","Sangue"}', 'Médio', 'paranormal', null, 20, '3d8 mental', 40, '2d20', '3d20+10', 23, '2d20+5', '3d20+10', '2d20', 140, 70, 'Balístico, corte e perfuração 10, Energia 20', 'Conhecimento', '{"agi":3,"for":3,"int":1,"pre":2,"vig":2}', null, '9m | 6', '[{"nome":"Trilha Digital","descricao":"Capta vibrações elétricas e de Energia em alcance extremo. Qualquer agente com aparelho eletrônico (celular, lanterna, relógio digital, escutas etc.) ou item amaldiçoado de Energia é percebido automaticamente (não pode pegá-lo desprevenido ou surpreendido) e fica vulnerável contra a criatura até se livrar de todos esses objetos."}]', '[{"tipo":"Padrão","nome":"Golpe Infectado, corpo a corpo x2","teste":"3d20+10","dano":"2d12+5 impacto"},{"tipo":"Reação","nome":"Frenesi Eletrônico","dano":"4d6+5 Energia (Reflexos DT 20 reduz à metade)","descricao":"Quando um ser em alcance curto usa poder, ritual, equipamento eletrônico ou item amaldiçoado de Energia, o marca-passo se move até ficar adjacente a ele e explode em um raio de 6m."},{"tipo":"Livre","nome":"Infecção de Equipamento","descricao":"Um ser que sofra dano do golpe rola 1d100. Com 51 ou mais, um equipamento dele vira item amaldiçoado de Energia (o mestre escolhe item e maldição). Com 50 ou menos, um equipamento é infectado pelo infecticídio; quem tocar no item pode se contaminar (Fortitude DT 20 evita; quem passa fica imune até o fim da cena)."}]', '/conteudo/as06/criaturas/marca-passo.webp', 128),
((select id from sources where slug = 'arquivos_secretos_06'), 'Estímulo', 320, 'Manifestação espectral do vírus infecticídio que adquiriu autoconsciência fora de um hospedeiro. Move-se e se fragmenta por sinais digitais e analógicos (bluetooth, wi-fi, rádio, televisão). Parece uma forma poligonal errática cujas arestas nunca chegam a formar uma esfera perfeita. A DT da presença perturbadora é rolada: 8d10.', '{"Energia","Sangue"}', 'Grande', 'paranormal', null, null, '9d6 mental', 95, '5d20+20', '5d20+20', 50, '4d20+15', '5d20+25', '5d20+20', 800, 400, 'Imune a dano (exceto Conhecimento) e a todas as condições', 'Conhecimento', '{"agi":5,"for":0,"int":5,"pre":5,"vig":4}', null, '12m | 8', '[{"nome":"Cogito Ergo Sum","descricao":"Um ser que falhe no teste contra a presença perturbadora (DT 8d10) é automaticamente infectado pelo vírus infecticídio (OPRPG, p. 292). Qualquer ser que tocar no Estímulo também é infectado automaticamente."}]', '[{"tipo":"Movimento","nome":"Sequestrar Sinal","descricao":"Teletransporta-se para qualquer espaço em alcance médio, desde que fique adjacente a um aparelho eletrônico."},{"tipo":"Padrão","nome":"Glitch","descricao":"Desaparece e reaparece, distorcendo a percepção de todos os seres em um raio de 9m: os alvos testam contra a presença perturbadora de novo."},{"tipo":"Padrão","nome":"Rodar Simulação","descricao":"Distorce a natureza física de um ser em alcance curto até o fim da cena: o maior atributo troca de lugar com o menor (Vontade DT 8d10 evita). Afeta apenas testes."},{"tipo":"Completa","nome":"Imergir","dano":"10d12 Energia (Fortitude DT 8d10 reduz à metade e evita o avanço da doença)","descricao":"Um ser em alcance curto sob efeito do infecticídio: a doença avança 1 estágio. Se morrer infectado, vira o princípio de uma horda de infecticídio (OPRPG, p. 267)."},{"tipo":"Completa","nome":"Sequestro de Atenção","descricao":"Projeta uma imagem hipnotizante para todos os seres infectados em um raio de 30m. Quem falhar em Vontade (DT 35) gasta todas as ações do próximo turno para ir até a criatura e tocá-la."}]', '/conteudo/as06/criaturas/estimulo.webp', 129),
((select id from sources where slug = 'arquivos_secretos_06'), 'Experimento Ssabáka', 180, 'Experimento russo de codinome Ssabáka, feito com ossadas amaldiçoadas encontradas na Sibéria Ocidental e que foi parar nas mãos das Indústrias Panacea. Criatura grotesca, descarnada, de ossos protuberantes, membros irregulares, força sobrenatural e cabeçorra dentada.', '{"Morte","Sangue"}', 'Médio', 'paranormal', null, 28, '6d6 mental', 60, '2d20+10', '3d20+15', 36, '4d20+15', '3d20+15', '2d20+10', 360, 180, 'Balístico, impacto e perfuração 10, Sangue 20', 'Energia', '{"agi":3,"for":3,"int":0,"pre":2,"vig":4}', null, '12m | 8', '[{"nome":"Fugitivo do Tempo","descricao":"Imune a qualquer efeito negativo relacionado ao tempo, natural ou paranormal (por exemplo, envelhecimento por idade, Decadência ou Paradoxo)."}]', '[{"tipo":"Padrão","nome":"Mordida, corpo a corpo","teste":"3d20+20","dano":"4d12+20 perfuração"},{"tipo":"Padrão","nome":"Garras, corpo a corpo x2","teste":"3d20+20","dano":"4d12+10 corte"},{"tipo":"Livre","nome":"Mastigar","descricao":"Ao acertar a mordida num alvo Grande ou menor, pode agarrá-lo com os dentes (teste 3d20+20): o alvo se move junto com a criatura até se libertar. Só mastiga um por vez e solta se fizer outra mordida."},{"tipo":"Movimento","nome":"Sofrimento Duradouro","descricao":"Despeja Lodo de Morte num alvo agarrado: ele recupera 3d8+3 PV atuais, mas perde 1d8+1 PV máximos permanentemente."},{"tipo":"Completa","nome":"Giro de Cauda","dano":"4d10+10 impacto + caído (Reflexos DT 28 reduz à metade e evita a condição)","descricao":"Atinge todos os seres adjacentes."}]', '/conteudo/as06/criaturas/ssabaka.webp', 130),
((select id from sources where slug = 'arquivos_secretos_07'), 'Raziel', 120, 'Vampiro ancestral, elegante e vingativo. Se Raziel ficar machucado ou enfurecido, a critério do mestre, muda de forma: use a ficha O Verdadeiro Raziel.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '2d20+5 (faro, percepção às cegas)', '4d20+10', 28, '3d20+10', '4d20+10', '2d20+5', 240, 120, 'Balístico, impacto e perfuração 10, Sangue 20', 'Morte', '{"agi":4,"for":3,"int":3,"pre":2,"vig":3}', 'Atletismo 3d20+10, Intimidação 2d20+10, Ocultismo 3d20+10', '9m | 6', '[{"nome":"Ignorar Dor","descricao":"Para efeitos dramáticos e de intimidação, Raziel ignora até mesmo a dor e parece imune a qualquer dano; passar em Intuição ou Percepção (DT 30) revela que essa imunidade não é real."},{"nome":"Monstruosidade","descricao":"Raziel já passou por incontáveis rituais para manter seus poderes e longevidade, sendo quase uma criatura do Outro Lado: recebe faro, percepção às cegas, resistência a balístico, impacto e perfuração 10 e Sangue 20, mas sofre vulnerabilidade a Morte (já contabilizado)."},{"nome":"Vingança","descricao":"Toda vez que um familiar de Raziel é morto, ele se sente impelido a rastrear e matar não só o alvo, mas a maioria das pessoas ligadas a ele ou no mesmo local. Se isso acontecer na frente dele, entra em Fúria Sanguinária."},{"nome":"Fúria Sanguinária","descricao":"Se ficar machucado ou enfurecido, a critério do mestre, muda de forma: use a ficha O Verdadeiro Raziel."}]', '[{"tipo":"Padrão","nome":"Garras, corpo a corpo x2","teste":"4d20+15, crítico 18","dano":"2d10+20 perfuração"},{"tipo":"Reação","nome":"Revidar e Estripar","descricao":"Uma vez por rodada, quando sofre um ataque corpo a corpo, revida com um ataque; se fizer isso, perde suas RD por 1 rodada."},{"tipo":"Livre","nome":"Abraço Sanguinolento","dano":"6d6 Sangue (Fortitude DT 23 reduz à metade)","descricao":"Se acertar as garras, pode agarrar o alvo (teste 4d20+15). Uma vez por rodada, como ação livre, morde um ser agarrado e recupera PV iguais à metade do dano causado."},{"tipo":"Movimento","nome":"Perseguir","descricao":"Uma vez por rodada, percorre o dobro do deslocamento na direção de um alvo que esteja querendo matar."},{"tipo":"Padrão","nome":"Endurecer Sangue","descricao":"Bombeia sangue para os músculos e recebe RD 5 até o fim da cena."},{"tipo":"Padrão","nome":"Fazer Sangrar","dano":"6d6 Sangue + sangrando (Fortitude DT 23 reduz à metade e evita a condição)","descricao":"Um ser em alcance curto. O sangramento desta habilidade causa a perda de 2d6 PV (em vez de 1d6)."},{"tipo":"Padrão","nome":"Maldição Sanguínea","descricao":"Um ser em alcance curto sofre –1d20 em todos os testes até o fim da cena (Fortitude DT 23 reduz para 1 rodada)."}]', '/conteudo/as07/criaturas/raziel.webp', 140),
((select id from sources where slug = 'arquivos_secretos_07'), 'O Verdadeiro Raziel', 200, 'A forma de Fúria Sanguinária de Raziel, assumida quando está machucado ou enfurecido.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '2d20+10 (faro, percepção às cegas)', '4d20+15', 38, '3d20+15', '4d20+15', '2d20+10', 400, 200, 'Balístico, impacto e perfuração 10, Sangue 20', 'Morte', '{"agi":4,"for":3,"int":3,"pre":2,"vig":3}', 'Atletismo 3d20+15, Intimidação 2d20+15, Ocultismo 3d20+15', '12m | 8', '[{"nome":"Monstruosidade","descricao":"Raziel já passou por incontáveis rituais para manter seus poderes e longevidade, sendo quase uma criatura do Outro Lado: recebe faro, percepção às cegas, resistência a balístico, impacto e perfuração 10 e Sangue 20, mas sofre vulnerabilidade a Morte (já contabilizado)."},{"nome":"Fúria Sanguinária","descricao":"Raziel assume essa forma quando está machucado ou enfurecido, a critério do mestre. Se estiver com menos de 200 PV ao assumir essa forma, fica imediatamente com 200 PV."},{"nome":"Sede Incontrolável","descricao":"Se Alvira estiver sendo ameaçada, gasta todas as ações para matar quem a ameaça. Caso contrário, foca no alvo com menos PV na cena, para finalizá-lo."}]', '[{"tipo":"Padrão","nome":"Garras, corpo a corpo x2","teste":"4d20+25, crítico 18","dano":"5d10+30 perfuração"},{"tipo":"Reação","nome":"Revidar e Estripar","descricao":"Uma vez por rodada, quando sofre um ataque corpo a corpo, revida com um ataque; se fizer isso, perde suas RD por 1 rodada."},{"tipo":"Livre","nome":"Abraço Sanguinolento","dano":"10d6 Sangue (Fortitude DT 29 reduz à metade)","descricao":"Se acertar as garras, pode agarrar o alvo (teste 4d20+15). Uma vez por rodada, como ação livre, morde um ser agarrado e recupera PV iguais à metade do dano causado."},{"tipo":"Movimento","nome":"Perseguir","descricao":"Uma vez por rodada, percorre o dobro do deslocamento na direção de um alvo que esteja querendo matar."},{"tipo":"Padrão","nome":"Bote Retalhador","dano":"10d10+30 perfuração + caído e sangrando","descricao":"Salta sobre 1 ser em até 3m. O alvo escolhe: Atacar (um único ataque como reação; se errar, sofre o dano e as condições; se acertar, metade e sem condições) ou Escapar (Reflexos DT 29; falha sofre tudo, sucesso reduz à metade e evita as condições)."}]', '/conteudo/as07/criaturas/raziel-verdadeiro.webp', 141),
((select id from sources where slug = 'arquivos_secretos_07'), 'Alvira', 120, 'Madre superior do clã de Raziel, ligada ao Sangue e às crenças distorcidas.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '4d20+10 (faro, percepção às cegas)', '3d20+10', 26, '2d20+5', '3d20+10', '4d20+10', 210, 105, 'Balístico, impacto e perfuração 10, Sangue 20', 'Morte', '{"agi":3,"for":1,"int":2,"pre":4,"vig":2}', 'Enganação 4d20+10, Medicina 2d20+10, Ocultismo 2d20+10, Religião 4d20+10', '9m | 6', '[{"nome":"Monstruosidade","descricao":"Alvira já passou por incontáveis rituais para manter seus poderes e longevidade, sendo quase uma criatura do Outro Lado: recebe faro, percepção às cegas, resistência a balístico, impacto e perfuração 10 e Sangue 20, mas sofre vulnerabilidade a Morte (já contabilizado)."},{"nome":"Madre Superior","descricao":"Qualquer aliado adjacente pode gastar uma ação de movimento para sugar o sangue de Alvira, causando-lhe 3d8+3 de dano; o aliado se cura na mesma quantidade (metade se ela estiver machucada). Não funciona se ela estiver morrendo."},{"nome":"Rituais (DT 23)","descricao":"Pode conjurar o ritual a seguir sem pagar seu custo de PE, até um limite de 10 PE por conjuração, usando a ação apropriada."}]', '[{"tipo":"Padrão","nome":"Cruz de Sangue, corpo a corpo x2","teste":"1d20+15","dano":"2d12+10 corte"},{"tipo":"Movimento","nome":"Clamor do Sangue Divino","descricao":"Uma vez por cena, todos os seres em alcance longo, à escolha dela, recebem +1d20 em testes de Agilidade, Força ou Vigor até o fim da cena."},{"tipo":"Padrão","nome":"Bolsa de Sangue","descricao":"Um ser em alcance longo recebe 3d8+3 PV; o que passar dos PV máximos vira PV temporários."},{"tipo":"Padrão","nome":"Sussurro Horripilante","descricao":"Faz a voz ressoar por alcance longo, com os mesmos efeitos de uma presença perturbadora (DT 23, 4d6 mental, NEX 50% é imune)."},{"tipo":"Completa","nome":"Ritual: Vampirismo (Sangue 2)","descricao":"Ritual complexo com diversas escolhas; veja o ritual Vampirismo."},{"tipo":"Completa","nome":"Titereira de Sangue","descricao":"Cordas de Sangue manipulam o corpo de 1 ser em alcance longo até o fim da cena; o alvo deve ter bebido ou sido curado pelo sangue dela. Em seu turno, gasta todas as ações fazendo o que ela ordenar (Fortitude DT 23 evita; pode repetir o teste no início de cada turno)."},{"tipo":"Completa","nome":"Transferir Sangue","descricao":"Uma vez por rodada, regurgita sangue em 1 ser adjacente: ela sofre 3d8+3 de dano e cura o alvo na mesma quantidade (metade se machucada). O alvo pode evitar a cura com Reflexos (DT 23). Não funciona se ela estiver morrendo."}]', '/conteudo/as07/criaturas/alvira.webp', 142),
((select id from sources where slug = 'arquivos_secretos_07'), 'Sabara', 100, 'Espadachim do clã de Raziel, mestra da espada e da adaga.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '2d20+5 (faro, percepção às cegas)', '3d20+10', 25, '2d20+5', '3d20+10', '2d20', 200, 100, 'Balístico, impacto e perfuração 10, Sangue 20', 'Morte', '{"agi":3,"for":3,"int":2,"pre":2,"vig":2}', 'Acrobacia 3d20+10, Atletismo 3d20+10, Sobrevivência 2d20+10', '9m | 6', '[{"nome":"Monstruosidade","descricao":"Sabara já passou por incontáveis rituais para manter seus poderes e longevidade, sendo quase uma criatura do Outro Lado: recebe faro, percepção às cegas, resistência a balístico, impacto e perfuração 10 e Sangue 20, mas sofre vulnerabilidade a Morte (já contabilizado)."}]', '[{"tipo":"Padrão","nome":"Espada e Adaga, corpo a corpo x2","teste":"3d20+15, crítico 18/x3","dano":"2d6+10 corte mais 2d4 Sangue"},{"tipo":"Padrão","nome":"Arremessar Faca, à distância (curto) x2","teste":"3d20+15, crítico 19","dano":"4d4+10 perfuração"},{"tipo":"Reação","nome":"Esquiva","descricao":"Uma vez por rodada, quando sofre um ataque, recebe +10 na Defesa contra ele."},{"tipo":"Reação","nome":"Mil Perfurações","descricao":"Se acertar os dois ataques de espada e adaga no mesmo alvo, deixa-o sangrando (Fortitude DT 21 evita); esse sangramento causa a perda de 2d6 PV (em vez de 1d6)."},{"tipo":"Reação","nome":"Ripostar e Revidar","descricao":"Uma vez por rodada, quando sofre um ataque corpo a corpo, se defende com um ataque de espada e adaga; se vencer o teste oposto, não sofre dano e causa 2d6+10 corte mais 2d4 Sangue ao atacante."},{"tipo":"Livre","nome":"Ringen am Schwert","dano":"6d6 Sangue (Fortitude DT 21 reduz à metade)","descricao":"Se acertar um ataque, pode agarrar o alvo (teste 3d20+15). Uma vez por rodada, como ação livre, morde um ser agarrado e recupera metade do dano em PV."},{"tipo":"Movimento","nome":"Perseguir","descricao":"Uma vez por rodada, percorre o dobro do deslocamento na direção de um alvo que esteja querendo matar."},{"tipo":"Padrão","nome":"Dança Armada","dano":"2d6+10 corte mais 2d4 Sangue (Reflexos DT 21 reduz à metade)","descricao":"Gira com os braços estendidos, golpeando todos os seres adjacentes à sua escolha."},{"tipo":"Padrão","nome":"Golpe Derrubante","dano":"2d6+10 corte mais 2d4 Sangue + caído (Reflexos DT 21 reduz à metade e evita a condição)","descricao":"Golpeia atrás da perna de 1 ser adjacente e mantém a ponta da espada no peito dele. Se a vítima se levantar ou agir, Sabara faz um ataque de espada e adaga como reação. Para rolar para longe, a vítima gasta uma ação padrão e testa Iniciativa (DT 23); se falhar, sofre o ataque de reação."}]', '/conteudo/as07/criaturas/sabara.webp', 143),
((select id from sources where slug = 'arquivos_secretos_07'), 'Velisar', 100, 'O cientista do clã, mestre de Zéfero. Percebe auras paranormais e armadilhas, e cria armadilhas de sangue.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '3d20+10 (faro, percepção às cegas)', '2d20+5', 25, '2d20', '2d20+5', '3d20+10', 180, 90, 'Balístico, impacto e perfuração 10, Sangue 20', 'Morte', '{"agi":2,"for":1,"int":4,"pre":3,"vig":2}', 'Artes 3d20+10, Atletismo 1d20+10, Ciências 4d20+10, Ocultismo 4d20+10, Tecnologia 4d20+10', '9m | 6', '[{"nome":"Monstruosidade","descricao":"Velisar já passou por incontáveis rituais para manter seus poderes e longevidade, sendo quase uma criatura do Outro Lado: recebe faro, percepção às cegas, resistência a balístico, impacto e perfuração 10 e Sangue 20, mas sofre vulnerabilidade a Morte (já contabilizado)."},{"nome":"Velisar Sabe","descricao":"Percebe auras paranormais e criaturas invisíveis ou semelhantes em alcance médio, e qualquer ameaça ou armadilha em um raio de 18m."}]', '[{"tipo":"Padrão","nome":"Garras, corpo a corpo x2","teste":"3d20+15, crítico 19","dano":"2d10+10 perfuração"},{"tipo":"Reação","nome":"Esquiva","descricao":"Uma vez por rodada, quando sofre um ataque, recebe +5 na Defesa contra ele."},{"tipo":"Livre","nome":"Abraço Sanguinolento","dano":"6d6 Sangue (Fortitude DT 21 reduz à metade)","descricao":"Se acertar as garras, pode agarrar o alvo (teste 3d20+15). Uma vez por rodada, como ação livre, morde um ser agarrado e recupera PV iguais à metade do dano causado."},{"tipo":"Movimento","nome":"Perseguir","descricao":"Uma vez por rodada, percorre o dobro do deslocamento na direção de um alvo que esteja querendo matar."},{"tipo":"Padrão","nome":"Armadilha Sanguinária","descricao":"Cria uma armadilha em espaço desocupado em alcance médio, ativada por quem ficar a 3m ou menos (Investigação DT 21 encontra; Ocultismo DT 21 desarma). Caixão de Sangue: 1 ser fica agarrado, caído e enredado (Reflexos DT 21 evita), e Velisar pode teletransportar o caixão para sua base. Explosão de Carne: todos a 3m sofrem 6d6 perfuração e ficam sangrando (Reflexos DT 21 reduz à metade e evita a condição). Gás Paralisante: todos a 3m ficam paralisados por 1d4+1 rodadas (Fortitude DT 21 muda para 1 rodada)."},{"tipo":"Padrão","nome":"Comandar Experimento","descricao":"Uma vez por rodada, comanda um de seus experimentos em alcance longo; se o experimento cumprir o comando até o próximo turno de Velisar e envolver um teste, recebe +1d20 nele."},{"tipo":"Padrão","nome":"Olhar da Curiosidade Mórbida","descricao":"Encara 1 ser em alcance médio: Reflexos (DT 21) para desviar o olhar ou Vontade (DT 21) para resistir. Se falhar, fica fascinado e só pode dar atenção e ser prestativo com Velisar até sofrer ação hostil ou ser sacudido."}]', '/conteudo/as07/criaturas/velisar.webp', 144),
((select id from sources where slug = 'arquivos_secretos_07'), 'Zéfero', 80, 'O "espécime" domesticado por Velisar em Praga: rápido, leve, com olfato estupendo. Faz o que o mestre manda em troca de carne ou sangue.', '{"Pessoa"}', 'Médio', 'mundana', 'Pessoa', null, null, null, '2d20+5 (faro, percepção às cegas)', '2d20+10', 23, '3d20+10', '2d20+5', '2d20', 140, 70, 'Balístico, impacto e perfuração 5, Sangue 10', 'Morte', '{"agi":2,"for":3,"int":0,"pre":2,"vig":2}', 'Atletismo 3d20+10', '12m | 8, Escalada 12m | 8', '[{"nome":"Demônio de Coleira","descricao":"Domesticado por Velisar; em troca de carne ou sangue, faz o que ele manda. Se Velisar morrer, pode ser domesticado por um novo dono que ofereça carne ou sangue e passe em Adestramento (DT 20)."},{"nome":"Fome Bestial","descricao":"Se Velisar estiver sendo ameaçado, gasta todas as ações para matar quem o ameaça. Caso contrário, foca no alvo com menos PV na cena."},{"nome":"Monstruosidade","descricao":"Zéfero já passou por incontáveis rituais para manter seus poderes e longevidade, sendo quase uma criatura do Outro Lado: recebe faro, percepção às cegas, resistência a balístico, impacto e perfuração 5 e Sangue 10, mas sofre vulnerabilidade a Morte (já contabilizado)."}]', '[{"tipo":"Padrão","nome":"Garras, corpo a corpo x2","teste":"3d20+10, crítico 19","dano":"1d10+10 perfuração"},{"tipo":"Padrão","nome":"Mordida Furiosa, corpo a corpo","teste":"3d20+10, crítico 19","dano":"3d12+20 Sangue"},{"tipo":"Reação","nome":"Bloqueio","descricao":"Uma vez por rodada, quando sofre um ataque, recebe RD 10 contra ele."},{"tipo":"Livre","nome":"Agarrão Lacerador","dano":"4d6 Sangue (Fortitude DT 20 reduz à metade)","descricao":"Se acertar a mordida, pode agarrar o alvo (teste 3d20+10). Uma vez por rodada, como ação livre, morde um ser agarrado e recupera metade do dano em PV."},{"tipo":"Livre","nome":"Dilacerar","descricao":"Se acertar os dois ataques de garras no mesmo alvo, causa +1d10 de dano de perfuração."}]', '/conteudo/as07/criaturas/zefero.webp', 145);

-- ===================== Aliados do AS06 =====================

insert into allies (source_id, tipo, name, descricao, bonus, habilidade_nome, habilidade, image_url, sort_order)
values
((select id from sources where slug = 'arquivos_secretos_06'), 'pessoa', 'Alice Cruzes', 'A diretora de algumas instalações da Panacea é uma mestra estrategista, capaz de analisar cenários complexos em segundos e coordenar seus aliados com precisão cirúrgica.', 'Você recebe +1d20 em Diplomacia e Tática.', 'Ainda é Útil', 'Uma vez por cena, quando está morrendo, você pode gastar 3 PE para ser estabilizado.', '/conteudo/as06/criaturas/alice-cruzes.webp', 20),
((select id from sources where slug = 'arquivos_secretos_06'), 'pessoa', 'Ketan Arjuna', 'Chefe de Segurança da Panacea, apto para qualquer tipo de combate, corpo a corpo ou à distância.', 'Sempre que causar dano, você causa +2d4 pontos de dano extra de um tipo à sua escolha (balístico, corte, impacto ou perfuração).', 'Fornecimento Secreto', 'Uma vez por missão, como uma ação de interlúdio, você pode gastar 3 PE para receber uma arma, que não seja amaldiçoada, de até categoria II. Se precisar, também recebe 2 pacotes de munição.', '/conteudo/as06/criaturas/ketan-arjuna.webp', 21),
((select id from sources where slug = 'arquivos_secretos_06'), 'pessoa', 'Laila Verdante', 'Laila possui um vasto conhecimento acerca da psique humana e de como o paranormal a afeta.', 'Você recebe resistência a dano mental 2.', 'Ajuda Especializada', 'Uma vez por dia, você pode gastar 3 PE para fazer um teste de Vontade usando o Ocultismo (4d20+10) de Laila, em vez de sua própria perícia.', '/conteudo/as06/criaturas/laila-verdante.webp', 22),
((select id from sources where slug = 'arquivos_secretos_06'), 'pessoa', 'Dr. Neruda', 'Um entre vários pesquisadores da Panacea; diferente da maioria, sabe muito bem o que faz lá. E adora o seu trabalho.', 'Sempre que causar dano com um ataque, o alvo também perde 1d4 PV.', 'Imunologista', 'Como uma ação de interlúdio, você pode gastar 3 PE para reduzir o estágio de uma doença que esteja afetando você em 1.', '/conteudo/as06/criaturas/dr-neruda.webp', 23);

-- ===================== Ritual Vampirismo (AS07) =====================

insert into rituals (source_id, name, elemento, circle, execution, range, target, duration, resistance, effect, discente_cost, discente_effect, discente_requires_circle, verdadeiro_cost, verdadeiro_effect, verdadeiro_requires_circle, verdadeiro_requires_affinity, image_url)
values ((select id from sources where slug = 'arquivos_secretos_07'), 'Vampirismo', 'sangue', 2, 'completa', 'toque', '1 pessoa', 'cena', null,
'Você absorve fragmentos de memórias inconscientes e instintivas de um ser. Este ritual transforma o corpo de uma pessoa viva ou morta em uma refeição paranormal até o fim da cena; com o fim da cena, o mesmo corpo não pode ser alvo deste ritual novamente. Qualquer pessoa que gaste 1 minuto comendo parte desse corpo recebe os efeitos dos vasos sanguíneos que escolheu consumir. Os mesmos vasos não podem ser consumidos mais de uma vez. Os efeitos duram até o final da cena.

Escolha quais vasos sanguíneos deseja consumir:
- Vasos da Visão: você visualiza flashes confusos da pessoa lutando pela própria vida. Você recebe +5 em testes de ataque.
- Vasos da Audição: você entende um pouco da linguagem utilizada pela pessoa. Se a pessoa conjurava rituais de 1º círculo, você pode escolher um para ser capaz de conjurar normalmente.
- Vasos do Paladar: você consegue sentir a vitalidade fluindo. Você recupera 2d8+2 PV.
- Vasos do Olfato: você consegue discernir com mais facilidade os rastros de um único ser ligado à pessoa. Você recebe +5 em testes para rastrear o ser.
- Vasos do Tato: você sente que pode reproduzir as capacidades da pessoa. Se a pessoa é treinada em perícias, você pode escolher uma para ser treinado. Se já for treinado na perícia escolhida, em vez disso, recebe +2 nela.',
5, 'Escolha quais vasos sanguíneos deseja consumir:
- Vasos da Visão: você visualiza flashes confusos da pessoa lutando pela própria vida. Você recebe +10 em testes de ataque.
- Vasos da Audição: você entende um pouco da linguagem utilizada pela pessoa. Se a pessoa conjurava rituais de 2º círculo, você pode escolher um para ser capaz de conjurar normalmente.
- Vasos do Paladar: você consegue sentir a vitalidade fluindo. Você recupera 3d8+3 PV.
- Vasos do Olfato: você consegue discernir com mais facilidade os rastros de um único ser ligado à pessoa. Você recebe +10 em testes para rastrear o ser.
- Vasos do Tato: você sente que pode reproduzir as capacidades da pessoa. Se a pessoa é veterana em perícias, você pode escolher uma para ser veterano. Se já for veterano na perícia escolhida, em vez disso, recebe +2 nela.', 3,
10, 'Escolha quais vasos sanguíneos deseja consumir:
- Vasos da Visão: você visualiza flashes confusos da pessoa lutando pela própria vida. Você recebe +15 em testes de ataque.
- Vasos da Audição: você entende um pouco da linguagem utilizada pela pessoa. Se a pessoa conjurava rituais de 3º círculo, você pode escolher um para ser capaz de conjurar normalmente.
- Vasos do Paladar: você consegue sentir a vitalidade fluindo. Você recupera 4d8+4 PV.
- Vasos do Olfato: você consegue discernir com mais facilidade os rastros de um único ser ligado à pessoa. Você recebe +15 em testes para rastrear o ser.
- Vasos do Tato: você sente que pode reproduzir as capacidades da pessoa. Se a pessoa é expert em perícias, você pode escolher uma para ser expert. Se já for expert na perícia escolhida, em vez disso, recebe +2 nela.', 4, true,
'/conteudo/as07/rituais/vampirismo.webp');

-- ===================== Pericia Religiao: novo uso (AS07) =====================

update skills
set description = description || '

**Resguardar Espírito (Treinado, DT 20).** Você pode gastar uma ação completa e fazer um teste de Religião para dedicar um breve rito religioso de proteção (rezas, oferendas, mantras etc.) a você ou uma pessoa adjacente. Se passar, o alvo recebe +2 em testes de Vontade até o final da cena. Se falhar, não pode tentar novamente na mesma pessoa até o final da cena. O bônus é fruto de como a fé pode motivar o ser humano, não tendo qualquer efeito paranormal. (Arquivos Secretos 07)'
where name = 'Religião' and description not like '%Resguardar Espírito%';
